NOM classe Pessoa {
    String nome;
    Int idade;

    NOM funcao iniciar(String n, Int i) {
        this.nome = n;
        this.idade = i;
    }
}

Array pessoas = [Pessoa("Ana", 30), Pessoa("Bruno", 15), Pessoa("Clara", 42)];
for (Pessoa p : pessoas) {
    se (p.idade >= 18) {
        escrever(p.nome + " e maior de idade");
    }
}

Int n = 6;
Int resultado = 1;
Int i = 2;
enquanto (i <= n) {
    resultado = resultado * i;
    i = i + 1;
}
escrever("6! =", resultado);

NOM classe Contador {
    Int valor;

    NOM funcao iniciar() {
        this.valor = 0;
    }

    NOM funcao incrementar() {
        this.valor = this.valor + 1;
    }
}

Contador c = Contador();
para (Int i = 0; i < 3; i = i + 1) {
    c.incrementar();
}
escrever("Valor final:", c.valor);

funcao somar_lista(Array lista) -> Int {
    Int total = 0;
    for (Int x : lista) {
        total = total + x;
    }
    return total;
}

escrever("Soma:", somar_lista([4, 8, 15]));
